//! Casa Mazatlan: what the INAH set draws by hand in 2D, lifted from its PDF - the survey of the existing
//! house (A010), the location map of the historic centre (A001) and the general notes' lines - as CAD
//! imports and text in drafting views, as Revit would hold them. Model mm at 1:100 (paper mm × 100).

import { inflateBase64 } from "./inflate.js";
const MZ_A010_Z = "";
const MZ_A001_MAP_Z = "";
const MZ_A001_TEXT_Z = "";
const MZ_PB1_Z = "";
const MZ_PA_Z = "";
const MZ_T_Z = "";
const MZ_ELEV_Z = "";
const MZ_S1_Z = "";
const MZ_S2_Z = "";
const MZ_S3_Z = "";
const MZ_S4_Z = "";
/** The hand sketches laid over some sheets (the set's own markup), as JPEGs; w, h their pixels. */
export const MZ_IMAGES = {
  A101: { url: "data:image/jpeg;base64,", w: 835, h: 1390 },
  A102: { url: "data:image/jpeg;base64,", w: 820, h: 1151 },
  A303: { url: "data:image/jpeg;base64,", w: 611, h: 277 },
  A304: { url: "data:image/jpeg;base64,", w: 714, h: 456 },
  A001: { url: "data:image/jpeg;base64,", w: 738, h: 418 }
};

let cache = null;
/** The drawings, inflated on first use. */
export function mazatlanPdf() {
  if (!cache) cache = { MZ_A010: JSON.parse(inflateBase64(MZ_A010_Z)), MZ_A001_MAP: JSON.parse(inflateBase64(MZ_A001_MAP_Z)), MZ_A001_TEXT: JSON.parse(inflateBase64(MZ_A001_TEXT_Z)), MZ_PB1: JSON.parse(inflateBase64(MZ_PB1_Z)), MZ_PA: JSON.parse(inflateBase64(MZ_PA_Z)), MZ_T: JSON.parse(inflateBase64(MZ_T_Z)), MZ_ELEV: JSON.parse(inflateBase64(MZ_ELEV_Z)), MZ_S1: JSON.parse(inflateBase64(MZ_S1_Z)), MZ_S2: JSON.parse(inflateBase64(MZ_S2_Z)), MZ_S3: JSON.parse(inflateBase64(MZ_S3_Z)), MZ_S4: JSON.parse(inflateBase64(MZ_S4_Z)) };
  return cache;
}
